package com.ptms.controller;import com.ptms.dto.*;import com.ptms.service.*;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/tickets") public class TicketInventoryController{private final TicketInventoryService s;public TicketInventoryController(TicketInventoryService s){this.s=s;}@GetMapping public List<TicketDto>all(){return s.all();}@GetMapping("/remaining") public List<TicketDto>remaining(){return s.remaining();}@PostMapping public TicketDto create(@Valid @RequestBody TicketDto q){return s.create(q);}@PutMapping("/{id}") public TicketDto update(@PathVariable Long id,@Valid @RequestBody TicketDto q){return s.update(id,q);}@DeleteMapping("/{id}") public void delete(@PathVariable Long id){s.delete(id);}@PostMapping("/bulk-scan") public List<TicketDto>bulk(@Valid @RequestBody BulkTicketScanRequest q){return s.bulk(q);}}
